    "Teacher + student WebRTC audio (separate tracks, 10-second windows) → speech-to-text with diarization → speaker-specific transcript → student learning signals teacher explanation risk → Confusion Confidence Score (CCS, deterministic) → GPT-5.6 teaching suggestion → automatic 3-option baseline poll → later teacher speech → implementation verification → follow-up poll → Bayesian Knowledge Tracing mastery + SQLite memory": {
      "fr": "Audio WebRTC enseignant + élève (pistes séparées, fenêtres de 10 secondes) → synthèse vocale avec diarisation → transcription spécifique au locuteur → signaux d'apprentissage de l'élève risque d'explication de l'enseignant → score de confiance de confusion (CCS, déterministe) → suggestion pédagogique GPT-5.6 → sondage de base automatique à 3 options → discours ultérieur de l'enseignant → vérification de la mise en œuvre → sondage de suivi → bayésien Maîtrise du Knowledge Tracing + mémoire SQLite",
      "de": "Lehrer + Schüler WebRTC-Audio (separate Spuren, 10-Sekunden-Fenster) → Speech-to-Text mit Diarisierung → sprecherspezifisches Transkript → Lernsignale des Schülers durch Erklärungsrisiko des Lehrers → Confusion Confidence Score (CCS, deterministisch) → GPT-5.6-Unterrichtsvorschlag → automatische 3-Optionen-Basisumfrage → spätere Lehrerrede → Implementierungsüberprüfung → Folgeumfrage → Bayesian Knowledge Tracing-Beherrschung + SQLite-Speicher"
    },
