    "b41bd8b6fda187f": {
      "fr": "<strong>Réalisations :</strong> Diplômé parmi les 10 % des meilleurs de la promotion, spécialisé en électronique et systèmes embarqués. Réalisation avec succès de l'un des meilleurs projets de thèse dans le domaine de la modélisation et du contrôle robotique, des systèmes embarqués et de la vision par ordinateur.",
      "de": "<strong>Erfolge:</strong> Abschluss unter den besten 10 % des Jahrgangs, Spezialisierung auf Elektronik und eingebettete Systeme. Eines der besten Abschlussarbeiten im Bereich Robotikmodellierung und -steuerung, eingebettete Systeme und Computer Vision erfolgreich abgeschlossen."
    },
