    "bb0d67b9699bf61": {
      "fr": "<strong>Résumé :</strong> A travaillé en tant que développeur embarqué stagiaire en se concentrant sur les systèmes en temps réel, l'intégration de l'IoT et le développement de micrologiciels embarqués à l'aide des plates-formes ESP32 et STM32.",
      "de": "<strong>Zusammenfassung:</strong> Arbeitete als angehender Embedded-Entwickler mit Schwerpunkt auf Echtzeitsystemen, IoT-Integration und eingebetteter Firmware-Entwicklung unter Verwendung der Plattformen ESP32 und STM32."
    },
    "b8e93ebdef3a1c4": {
      "fr": "Mise en œuvre d'un <strong style=\"color: var(--clr-accent)\">système d'exploitation en temps réel</strong> sur <strong style=\"color: var(--clr-accent)\">ESP32</strong>, améliorant la planification des tâches, la précision du timing et la réactivité globale du système pour les applications sensibles au facteur temps.",
      "de": "Implementierte ein <strong style=\"color: var(--clr-accent)\">Echtzeitbetriebssystem</strong> auf <strong style=\"color: var(--clr-accent)\">ESP32</strong> und verbesserte die Aufgabenplanung, Timing-Genauigkeit und allgemeine Systemreaktionsfähigkeit für zeitkritische Anwendungen."
    },
    "bc98932e23c190e": {
      "fr": "Développement de fonctionnalités de communication basées sur l'IoT en utilisant <strong style=\"color: var(--clr-accent)\">ESP32</strong> et <strong style=\"color: var(--clr-accent)\">STM32 Blue Pill</strong>, permettant un échange de données fiable et des capacités de surveillance à distance.",
      "de": "Entwicklung von IoT-basierten Kommunikationsfunktionen unter Verwendung von <strong style=\"color: var(--clr-accent)\">ESP32</strong> und <strong style=\"color: var(--clr-accent)\">STM32 Blue Pill</strong>, die einen zuverlässigen Datenaustausch und Fernüberwachungsfunktionen ermöglichen."
    },
    "b3ab976c1c871f3": {
      "fr": "Acquisition d'une expérience pratique dans le développement de micrologiciels embarqués, l'interfaçage de périphériques, les microcontrôleurs basés sur ARM et le débogage de systèmes embarqués en temps réel.",
      "de": "Er sammelte praktische Erfahrungen mit der Entwicklung eingebetteter Firmware, Peripherieschnittstellen, ARM-basierten Mikrocontrollern und dem Debuggen eingebetteter Echtzeitsysteme."
    },
    "bdb7b200a7f42e6": {
      "fr": "Application des compétences acquises et mises en pratique à un <strong style=\"color: var(--clr-accent)\">dispositif de gestion de l'irrigation agricole</strong>, conçu pour automatiser le contrôle de l'eau en fonction des entrées de capteurs.",
      "de": "Wendete die erlernten und geübten Fähigkeiten auf ein <strong style=\"color: var(--clr-accent)\">Bewässerungsmanagementgerät für die Landwirtschaft</strong> an, das die Wassersteuerung auf der Grundlage von Sensoreingaben automatisieren soll."
    },
