    "b18c132e335a78d": {
      "fr": "<strong>Résumé :</strong> A été chef du chapitre sur la robotique et l'automatisation de la branche étudiante de l'IEEE PIEAS. A dirigé une équipe d'étudiants bénévoles et a joué un rôle clé dans l'organisation de formations techniques, d'ateliers et de concours liés à la robotique et aux systèmes embarqués.",
      "de": "<strong>Zusammenfassung:</strong> Diente als Leiter des Kapitels „Robotik und Automatisierung“ in der IEEE PIEAS Student Branch. Leitete ein Team studentischer Freiwilliger und spielte eine Schlüsselrolle bei der Organisation technischer Schulungen, Workshops und Wettbewerbe im Zusammenhang mit Robotik und eingebetteten Systemen."
    },
    "b47bc878265b715": {
      "fr": "Dirigé le chapitre sur la robotique et l'automatisation et coordonné une équipe de bénévoles pour planifier et exécuter les activités techniques.",
      "de": "Leiter des Kapitels „Robotik und Automatisierung“ und koordinierte ein Team von Freiwilligen zur Planung und Durchführung technischer Aktivitäten."
    },
    "b5e1b34cc24830e": {
      "fr": "Camps de formation et ateliers organisés couvrant les principes fondamentaux de la robotique, de la programmation C embarquée et des systèmes basés sur des microcontrôleurs.",
      "de": "Organisierte Schulungslager und Workshops zu den Grundlagen der Robotik, der eingebetteten C-Programmierung und mikrocontrollerbasierten Systemen."
    },
    "b258aa0b5af6058": {
      "fr": "J'ai moi-même animé des séances sur la modélisation CAO, la simulation robotique CoppeliaSim et les concepts de base de la programmation embarquée.",
      "de": "Ich selbst habe Sitzungen zu CAD-Modellierung, CoppeliaSim-Robotiksimulation und grundlegenden Konzepten der eingebetteten Programmierung gehalten."
    },
    "b75fe2d3b37e119": {
      "fr": "Webinaires organisés, concours et événements de sensibilisation pour encourager la participation des étudiants aux activités techniques de l'IEEE.",
      "de": "Organisierte Webinare, Wettbewerbe und Outreach-Veranstaltungen, um Studenten zur Teilnahme an technischen IEEE-Aktivitäten zu ermutigen."
    },
    "ba6eec45ef81da2": {
      "fr": "Organisation d'événements IEEE majeurs, notamment les célébrations de la Journée IEEE et l'ISYWSC, une conférence IEEE au niveau national.",
      "de": "Gastgeber wichtiger IEEE-Veranstaltungen, darunter Feierlichkeiten zum IEEE-Tag und ISYWSC, eine IEEE-Konferenz auf nationaler Ebene."
    },
    "b8e94d071387096": {
      "fr": "Ce rôle a renforcé mes compétences en leadership, en prise de parole en public et en mentorat tout en m'apportant une expérience précieuse dans la gestion d'équipes techniques et l'organisation d'activités étudiantes à grande échelle.",
      "de": "Diese Rolle stärkte meine Fähigkeiten in den Bereichen Führung, öffentliches Reden und Mentoring und vermittelte mir gleichzeitig wertvolle Erfahrungen in der Leitung technischer Teams und der Organisation groß angelegter studentischer Aktivitäten."
    },
