    "b6db452ac37ba31": {
      "fr": "<strong>Résumé :</strong> A travaillé en tant qu'ingénieur de laboratoire adjoint dans le laboratoire de robotique de PIEAS, aidant les étudiants à apprendre la robotique, la simulation et les systèmes de contrôle embarqués grâce à des instructions pratiques et des conseils pratiques en laboratoire.",
      "de": "<strong>Zusammenfassung:</strong> Arbeitete als stellvertretender Laboringenieur im Robotiklabor von PIEAS und unterstützte Studenten beim Erlernen von Robotik, Simulation und eingebetteten Steuerungssystemen durch praktische Anleitung und praktische Laboranleitung."
    },
    "b97bec93664eba5": {
      "fr": "Formation des étudiants en <strong style=\"color: var(--clr-accent)\">modélisation CAO</strong> et simulation robotique à l'aide de <strong style=\"color: var(--clr-accent)\">SolidWorks</strong> et <strong style=\"color: var(--clr-accent)\">CoppeliaSim</strong>.",
      "de": "Unterrichtete Schüler in <strong style=\"color: var(--clr-accent)\">CAD-Modellierung</strong> und Robotersimulation unter Verwendung von <strong style=\"color: var(--clr-accent)\">SolidWorks</strong> und <strong style=\"color: var(--clr-accent)\">CoppeliaSim</strong>."
    },
    "bbca1ea75a4b7e5": {
      "fr": "Enseigné <strong style=\"color: var(--clr-accent)\">MATLAB</strong> pour les tests, la modélisation, l'analyse de contrôle et la visualisation de données de systèmes robotiques.",
      "de": "Unterrichtete <strong style=\"color: var(--clr-accent)\">MATLAB</strong> für Robotersystemtests, Modellierung, Steuerungsanalyse und Datenvisualisierung."
    },
    "b227cd9199153d1": {
      "fr": "A guidé les étudiants dans la mise en œuvre de systèmes de contrôle robotique à l'aide de <strong style=\"color: var(--clr-accent)\">microcontrôleurs</strong> et de <strong style=\"color: var(--clr-accent)\">programmation intégrée</strong>.",
      "de": "Anleitung der Schüler bei der Implementierung von Robotersteuerungssystemen mithilfe von <strong style=\"color: var(--clr-accent)\">Mikrocontrollern</strong> und <strong style=\"color: var(--clr-accent)\">eingebetteter Programmierung</strong>."
    },
    "bf72ff75202223d": {
      "fr": "Aide à l'intégration de composants matériels tels que des capteurs, des moteurs et des contrôleurs pour créer des projets robotiques pratiques.",
      "de": "Unterstützung bei der Integration von Hardwarekomponenten wie Sensoren, Motoren und Steuerungen, um praktische Robotikprojekte zu erstellen."
    },
    "b13e5b422b861e7": {
      "fr": "A aidé les étudiants à comprendre le lien entre la conception mécanique, les algorithmes de contrôle et la mise en œuvre intégrée.",
      "de": "Unterstützte Studenten beim Verständnis des Zusammenhangs zwischen mechanischem Design, Steuerungsalgorithmen und eingebetteter Implementierung."
    },
    "b642504b04e35df": {
      "fr": "Ce rôle a renforcé mes compétences de mentorat et approfondi ma compréhension pratique des systèmes robotiques, des outils de simulation et du contrôle embarqué.",
      "de": "Diese Rolle stärkte meine Mentoring-Fähigkeiten und vertiefte mein praktisches Verständnis von Robotiksystemen, Simulationstools und eingebetteter Steuerung."
    },
