      "fr": "<strong>Filet Élastique (LDL) :</strong> 2ème test <span class=\"metric\">26.13</span> · Δ <span class=\"metric\">20.40</span>",
      "de": "<strong>Elastisches Netz (LDL):</strong> 2. Test <span class=\"metric\">26,13</span> · Δ <span class=\"metric\">20,40</span>"
