    "b842932fd3641df": {
      "fr": "Module complémentaire servo (PWM)",
      "de": "Servo-Add-On (PWM)"
    },
    "b56c3e378bb05e1": {
      "fr": "Un contrôleur PWM léger fait varier la largeur d'impulsion pour définir l'angle du servo. Les valeurs de seuil peuvent être mises à jour pour balayer ou verrouiller à un point défini, permettant des analyses de zone simples.",
      "de": "Ein leichter PWM-Controller variiert die Impulsbreite, um den Servowinkel einzustellen. Schwellenwerte können aktualisiert werden, um an einem festgelegten Punkt zu fegen oder zu sperren, was einfache Bereichsscans ermöglicht."
    },
