      "fr": "<strong>Enregistrement des données</strong> (étapes et BPM moyen) pour flasher ; Vue « Historique » dans l'interface utilisateur.",
      "de": "<strong>Datenprotokollierung</strong> (Schritte und durchschnittlicher BPM) zum Flashen; Ansicht „Verlauf“ in der Benutzeroberfläche."
