    "b47245bb992e079": {
      "fr": "ESP32 · FreeRTOS · Épinglage de tâches double cœur · Files d'attente et mutex · Minuteries logicielles · MPU6050 · SSD1306 OLED · I²C · NTP · Arduino IoT Cloud",
      "de": "ESP32 · FreeRTOS · Dual-Core-Task-Pinning · Warteschlangen und Mutex · Software-Timer · MPU6050 · SSD1306 OLED · I²C · NTP · Arduino IoT Cloud"
    },
    "b6c9459052a0d50": {
      "fr": "<span class=\"metric\">Labo ouvert</span> <span class=\"metric\">Prototype matériel</span> <span class=\"metric\">décembre 2023</span>",
      "de": "<span class=\"metric\">Offenes Labor</span> <span class=\"metric\">Hardware-Prototyp</span> <span class=\"metric\">Dezember 2023</span>"
    },
    "b20b4a1c06e93ef": {
      "fr": "Un prototype de montre intelligente fonctionnel construit sur du matériel réel. Un <strong>ESP32</strong> exécutant <strong>FreeRTOS</strong> affiche le temps, la fréquence cardiaque et le nombre de pas sur un <strong>OLED</strong>, mesure la fréquence cardiaque avec un capteur de pouls et compte les pas avec un accéléromètre <strong>MPU6050</strong>. Il diffuse également tout sur un tableau de bord <strong>Arduino IoT Cloud</strong> pour une surveillance à distance.",
      "de": "Ein funktionierender Smartwatch-Prototyp, der auf echter Hardware basiert. Ein <strong>ESP32</strong> mit <strong>FreeRTOS</strong> zeigt Zeit, Herzfrequenz und Schrittzahl auf einem <strong>OLED</strong> an, misst die Herzfrequenz mit einem Pulssensor und zählt Schritte mit einem <strong>MPU6050</strong>-Beschleunigungsmesser. Außerdem wird alles zur Fernüberwachung an ein <strong>Arduino IoT Cloud</strong>-Dashboard gestreamt."
    },
