      "fr": "<strong>Économie d'énergie :</strong> l'écran se réveille lorsque vous appuyez sur un bouton et s'éteint automatiquement après <strong>30 s</strong> d'inactivité.",
      "de": "<strong>Energiesparen:</strong> Das Display wird auf Knopfdruck aktiviert und nach <strong>30 s</strong> Inaktivität automatisch ausgeschaltet."
