    "b2cc9cedb0a4510": {
      "fr": "Chaque fonction s'exécute comme sa propre tâche, <strong>épinglée à l'un des deux cœurs du ESP32</strong>. Les tâches de capteur et de temps s'exécutent sur le cœur 0. La tâche d'affichage et de cloud s'exécute sur le cœur 1 avec une priorité inférieure, de sorte que les capteurs ne sont jamais affamés.",
      "de": "Jede Funktion wird als eigene Aufgabe ausgeführt, <strong>an einen der beiden Kerne des ESP32 angeheftet</strong>. Sensor- und Zeitaufgaben werden auf Kern 0 ausgeführt. Die Anzeige- und Cloud-Aufgabe wird auf Kern 1 mit einer niedrigeren Priorität ausgeführt, sodass die Sensoren nie überlastet werden."
    },
