    "b75fac715f75c4c": {
      "fr": "Un <strong>mutex I²C</strong> protège le bus partagé, de sorte que l'OLED et le MPU6050 ne soient jamais accédés en même temps par des tâches différentes.",
      "de": "Ein <strong>I²C-Mutex</strong> schützt den gemeinsam genutzten Bus, sodass auf die OLED und die MPU6050 niemals gleichzeitig von verschiedenen Aufgaben zugegriffen wird."
    },
    "b1b1c6fc4b69ace": {
      "fr": "Gestion de l'alimentation de l'affichage",
      "de": "Energieverwaltung des Displays"
    },
    "b8bc10bf94141d8": {
      "fr": "Le bouton <strong>ISR</strong> (ou le commutateur cloud) démarre ou réinitialise un <strong>minuteur logiciel ponctuel de 30 s</strong> et envoie \"écran allumé\" à la tâche d'affichage.",
      "de": "Die Schaltfläche <strong>ISR</strong> (oder der Cloud-Schalter) startet oder setzt einen <strong>30 Sekunden-Software-Timer</strong> zurück und sendet „Bildschirm ein“ an die Anzeigeaufgabe."
    },
    "bfec671acd8641e": {
      "fr": "Lorsque la minuterie expire, son rappel envoie \"écran éteint\" et la tâche d'affichage efface l'OLED.",
      "de": "Wenn der Timer abläuft, sendet sein Rückruf „Bildschirm aus“ und die Anzeigeaufgabe schaltet die OLED aus."
    },
