    "b5207310a624843": {
      "fr": "<strong>bPM</strong> (CloudHeartRate), <strong>steps</strong> (int) et <strong>lED</strong> (CloudLight) : lecture seule, envoyé en cas de modification.",
      "de": "<strong>bPM</strong> (CloudHeartRate), <strong>steps</strong> (int) und <strong>lED</strong> (CloudLight): schreibgeschützt, bei Änderung gesendet."
    },
